import java.io.*;
import java.util.*;

public class Main {
    static class PairPos {
        int r1 = -1, c1 = -1, r2 = -1, c2 = -1;
    }

    static int n, m;
    static int[][] grid;
    static int maxId;
    static PairPos[] pairs;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();
        grid = new int[n][m];

        maxId = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = fs.nextInt();
                if (grid[i][j] > maxId) maxId = grid[i][j];
            }
        }

        pairs = new PairPos[maxId + 1];
        for (int i = 1; i <= maxId; i++) pairs[i] = new PairPos();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int id = grid[i][j];
                PairPos p = pairs[id];
                if (p.r1 == -1) {
                    p.r1 = i;
                    p.c1 = j;
                } else {
                    p.r2 = i;
                    p.c2 = j;
                }
            }
        }

        int totalCells = n * m;
        int totalPairs = totalCells / 2;

        int[][] target = new int[n][m];
        int idx = 0;
        for (int id = 1; id <= maxId; id++) {
            PairPos p = pairs[id];
            if (p.r1 == -1) continue;
            int r1 = idx / m;
            int c1 = idx % m;
            idx++;
            int r2 = idx / m;
            int c2 = idx % m;
            idx++;
            target[r1][c1] = id;
            target[r2][c2] = id;
        }

        int[][] cost = new int[maxId + 1][2];
        for (int id = 1; id <= maxId; id++) {
            PairPos p = pairs[id];
            if (p.r1 == -1) continue;
            int r1 = p.r1, c1 = p.c1, r2 = p.r2, c2 = p.c2;

            int tIndex1 = (id - 1) * 2;
            int tr1 = tIndex1 / m;
            int tc1 = tIndex1 % m;
            int tIndex2 = tIndex1 + 1;
            int tr2 = tIndex2 / m;
            int tc2 = tIndex2 % m;

            int option1 = (r1 == tr1 && c1 == tc1 ? 0 : 1) + (r2 == tr2 && c2 == tc2 ? 0 : 1);
            int option2 = (r1 == tr2 && c1 == tc2 ? 0 : 1) + (r2 == tr1 && c2 == tc1 ? 0 : 1);

            cost[id][0] = option1;
            cost[id][1] = option2;
        }

        int[][] dp = new int[maxId + 1][2];
        for (int i = 0; i <= maxId; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE / 2);
        }
        dp[0][0] = 0;

        for (int id = 1; id <= maxId; id++) {
            PairPos p = pairs[id];
            if (p.r1 == -1) {
                dp[id][0] = dp[id - 1][0];
                dp[id][1] = dp[id - 1][1];
                continue;
            }
            for (int prev = 0; prev < 2; prev++) {
                if (dp[id - 1][prev] >= Integer.MAX_VALUE / 2) continue;
                for (int cur = 0; cur < 2; cur++) {
                    int add = cost[id][cur];
                    dp[id][cur] = Math.min(dp[id][cur], dp[id - 1][prev] + add);
                }
            }
        }

        int answer = Math.min(dp[maxId][0], dp[maxId][1]);
        System.out.println(answer);
    }

    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
