import java.io.*;
import java.util.*;

public class Main {
    static class PairPos {
        int r1 = -1, c1 = -1, r2 = -1, c2 = -1;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int m = fs.nextInt();
        int[][] a = new int[n][m];

        int maxId = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                a[i][j] = fs.nextInt();
                if (a[i][j] > maxId) maxId = a[i][j];
            }
        }

        PairPos[] pairs = new PairPos[maxId + 1];
        for (int i = 1; i <= maxId; i++) pairs[i] = new PairPos();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int id = a[i][j];
                PairPos p = pairs[id];
                if (p.r1 == -1) {
                    p.r1 = i;
                    p.c1 = j;
                } else {
                    p.r2 = i;
                    p.c2 = j;
                }
            }
        }

        int totalCells = n * m;
        int half = totalCells / 2;

        int[] blackRow = new int[half];
        int[] blackCol = new int[half];
        int[] whiteRow = new int[half];
        int[] whiteCol = new int[half];

        int bIdx = 0, wIdx = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((i + j) % 2 == 0) {
                    blackRow[bIdx] = i;
                    blackCol[bIdx] = j;
                    bIdx++;
                } else {
                    whiteRow[wIdx] = i;
                    whiteCol[wIdx] = j;
                    wIdx++;
                }
            }
        }

        int[][] cost = new int[half][half];

        for (int i = 0; i < half; i++) {
            int br = blackRow[i];
            int bc = blackCol[i];
            for (int j = 0; j < half; j++) {
                int wr = whiteRow[j];
                int wc = whiteCol[j];

                int c = 0;
                for (int id = 1; id <= maxId; id++) {
                    PairPos p = pairs[id];
                    int r1 = p.r1, c1 = p.c1, r2 = p.r2, c2 = p.c2;

                    int d1 = Math.abs(r1 - br) + Math.abs(c1 - bc) +
                             Math.abs(r2 - wr) + Math.abs(c2 - wc);
                    int d2 = Math.abs(r2 - br) + Math.abs(c2 - bc) +
                             Math.abs(r1 - wr) + Math.abs(c1 - wc);
                    int best = Math.min(d1, d2);
                    c += best;
                }
                cost[i][j] = c;
            }
        }

        int answer = hungarian(cost);
        System.out.println(answer);
    }

    // Hungarian algorithm for minimum cost perfect matching in bipartite graph
    // cost matrix size: n x n
    static int hungarian(int[][] cost) {
        int n = cost.length;
        int[] u = new int[n + 1];
        int[] v = new int[n + 1];
        int[] p = new int[n + 1];
        int[] way = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            p[0] = i;
            int j0 = 0;
            int[] minv = new int[n + 1];
            boolean[] used = new boolean[n + 1];
            Arrays.fill(minv, Integer.MAX_VALUE);
            do {
                used[j0] = true;
                int i0 = p[j0];
                int delta = Integer.MAX_VALUE;
                int j1 = 0;
                for (int j = 1; j <= n; j++) {
                    if (!used[j]) {
                        int cur = cost[i0 - 1][j - 1] - u[i0] - v[j];
                        if (cur < minv[j]) {
                            minv[j] = cur;
                            way[j] = j0;
                        }
                        if (minv[j] < delta) {
                            delta = minv[j];
                            j1 = j;
                        }
                    }
                }
                for (int j = 0; j <= n; j++) {
                    if (used[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p[j0] != 0);

            do {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0 != 0);
        }

        int result = 0;
        for (int j = 1; j <= n; j++) {
            int i = p[j];
            result += cost[i - 1][j - 1];
        }
        return result;
    }

    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

