public class Main {
    static class PairPos {
        int r1 = -1, c1 = -1, r2 = -1, c2 = -1;
    }

    static int n, m;
    static int[][] grid;
    static int[][] id;
    static int[] pairId;
    static int[] color;
    static int N;
    static ArrayList<Integer>[] adj;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        m = fs.nextInt();
        grid = new int[n][m];

        int maxPair = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = fs.nextInt();
                if (grid[i][j] > maxPair) maxPair = grid[i][j];
            }
        }

        PairPos[] pairs = new PairPos[maxPair + 1];
        for (int i = 1; i <= maxPair; i++) pairs[i] = new PairPos();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int v = grid[i][j];
                PairPos p = pairs[v];
                if (p.r1 == -1) {
                    p.r1 = i; p.c1 = j;
                } else {
                    p.r2 = i; p.c2 = j;
                }
            }
        }

        N = n * m;
        id = new int[n][m];
        int idx = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                id[i][j] = idx++;

        pairId = new int[N];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                pairId[id[i][j]] = grid[i][j];

        color = new int[N];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                color[id[i][j]] = (i + j) & 1;

        adj = new ArrayList[N];
        for (int i = 0; i < N; i++) adj[i] = new ArrayList<>();

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int u = id[i][j];
                if (color[u] == 0) {
                    for (int k = 0; k < 4; k++) {
                        int ni = i + dr[k], nj = j + dc[k];
                        if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
                        int v = id[ni][nj];
                        if (pairId[u] == pairId[v]) {
                            adj[u].add(v);
                        }
                    }
                }
            }
        }

        int leftCount = 0;
        for (int i = 0; i < N; i++) if (color[i] == 0) leftCount++;

        int[] pairCount = new int[maxPair + 1];
        for (int i = 0; i < N; i++) pairCount[pairId[i]]++;

        int totalPairs = 0;
        for (int p = 1; p <= maxPair; p++) if (pairCount[p] > 0) totalPairs++;

        int maxMatching = hopcroftKarp(leftCount);

        int result = 2 * totalPairs - 2 * maxMatching;
        System.out.println(result);
    }

    static int hopcroftKarp(int leftCount) {
        int[] pairU = new int[N];
        int[] pairV = new int[N];
        int[] dist = new int[N];

        Arrays.fill(pairU, -1);
        Arrays.fill(pairV, -1);

        int matching = 0;

        while (bfs(pairU, pairV, dist, leftCount)) {
            for (int u = 0; u < N; u++) {
                if (color[u] == 0 && pairU[u] == -1) {
                    if (dfs(u, pairU, pairV, dist)) {
                        matching++;
                    }
                }
            }
        }
        return matching;
    }

    static boolean bfs(int[] pairU, int[] pairV, int[] dist, int leftCount) {
        ArrayDeque<Integer> q = new ArrayDeque<>();
        Arrays.fill(dist, -1);

        for (int u = 0; u < N; u++) {
            if (color[u] == 0) {
                if (pairU[u] == -1) {
                    dist[u] = 0;
                    q.add(u);
                }
            }
        }

        boolean found = false;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                int pu = pairV[v];
                if (pu != -1 && dist[pu] == -1) {
                    dist[pu] = dist[u] + 1;
                    q.add(pu);
                }
                if (pu == -1) {
                    found = true;
                }
            }
        }
        return found;
    }

    static boolean dfs(int u, int[] pairU, int[] pairV, int[] dist) {
        for (int v : adj[u]) {
            int pu = pairV[v];
            if (pu == -1 || (dist[pu] == dist[u] + 1 && dfs(pu, pairU, pairV, dist))) {
                pairU[u] = v;
                pairV[v] = u;
                return true;
            }
        }
        dist[u] = -1;
        return false;
    }

    // FastScanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}

