    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int m = fs.nextInt();
        int[][] a = new int[n][m];

        int maxId = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                a[i][j] = fs.nextInt();
                if (a[i][j] > maxId) maxId = a[i][j];
            }
        }

        // store positions of each shoe id
        Pos[] first = new Pos[maxId + 1];
        Pos[] second = new Pos[maxId + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int id = a[i][j];
                if (first[id] == null) first[id] = new Pos(i, j);
                else second[id] = new Pos(i, j);
            }
        }

        int totalCells = n * m;
        int leftCount = (totalCells + 1) / 2;
        int rightCount = totalCells / 2;

        int[] leftIndex = new int[n * m];
        int[] rightIndex = new int[n * m];
        Arrays.fill(leftIndex, -1);
        Arrays.fill(rightIndex, -1);

        int L = 0, R = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int idx = i * m + j;
                if (((i + j) & 1) == 0) {
                    leftIndex[idx] = L++;
                } else {
                    rightIndex[idx] = R++;
                }
            }
        }

        int maxN = Math.max(L, R);
        int[][] cost = new int[L][R];
        final int INF = 1_000_000_000;
        for (int i = 0; i < L; i++) Arrays.fill(cost[i], INF);

        for (int id = 1; id <= maxId; id++) {
            Pos p1 = first[id];
            Pos p2 = second[id];
            int r1 = p1.r, c1 = p1.c;
            int r2 = p2.r, c2 = p2.c;
            int idx1 = r1 * m + c1;
            int idx2 = r2 * m + c2;

            boolean adj = Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1;

            if (((r1 + c1) & 1) == 0) {
                int li = leftIndex[idx1];
                int ri = rightIndex[idx2];
                int cst = 2;
                if (adj) cst = 0;
                else if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 2) cst = 1;
                cost[li][ri] = Math.min(cost[li][ri], cst);
            } else {
                int li = leftIndex[idx2];
                int ri = rightIndex[idx1];
                int cst = 2;
                if (adj) cst = 0;
                else if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 2) cst = 1;
                cost[li][ri] = Math.min(cost[li][ri], cst);
            }
        }

        int answer = hungarian(cost, L, R);
        System.out.println(answer);
    }

    // Hungarian algorithm for rectangular cost matrix (L x R), L <= R
    static int hungarian(int[][] a, int n, int m) {
        int[] u = new int[n + 1];
        int[] v = new int[m + 1];
        int[] p = new int[m + 1];
        int[] way = new int[m + 1];
        final int INF = 1_000_000_000;

        for (int i = 1; i <= n; i++) {
            p[0] = i;
            int j0 = 0;
            int[] minv = new int[m + 1];
            boolean[] used = new boolean[m + 1];
            Arrays.fill(minv, INF);
            do {
                used[j0] = true;
                int i0 = p[j0], delta = INF, j1 = 0;
                for (int j = 1; j <= m; j++) {
                    if (!used[j]) {
                        int cur = a[i0 - 1][j - 1] - u[i0] - v[j];
                        if (cur < minv[j]) {
                            minv[j] = cur;
                            way[j] = j0;
