                for (int j = 0; j <= m; j++) {
                    if (used[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p[j0] != 0);
            do {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0 != 0);
        }

        int result = 0;
        for (int j = 1; j <= m; j++) {
            if (p[j] > 0 && p[j] <= n) {
                result += a[p[j] - 1][j - 1];
            }
        }
        return result;
    }

