public class Main {
    static class Pos {
        int r, c;
        Pos(int r, int c) { this.r = r; this.c = c; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int[][] a = new int[n][m];
        int maxId = 0;
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < m; j++) {
                a[i][j] = Integer.parseInt(st.nextToken());
                if (a[i][j] > maxId) maxId = a[i][j];
            }
        }

        // positions of each shoe id (exactly two positions)
        Pos[] p1 = new Pos[maxId + 1];
        Pos[] p2 = new Pos[maxId + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int id = a[i][j];
                if (p1[id] == null) p1[id] = new Pos(i, j);
                else p2[id] = new Pos(i, j);
            }
        }

        int N = n * m;
        int[] row = new int[N];
        int[] col = new int[N];
        int idx = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                row[idx] = i;
                col[idx] = j;
                idx++;
            }

        // bipartite graph: left = all cells, right = all cells
        // cost[i][j] = cost to place one shoe of its pair at left cell i and the other at right cell j (adjacent)
        // but we only allow edges where cells are adjacent
        int INF = 1_000_000_000;
        int[][] cost = new int[N][N];
        for (int i = 0; i < N; i++) Arrays.fill(cost[i], INF);

        // precompute which cell index corresponds to (r,c)
        int[][] idCell = new int[n][m];
        idx = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                idCell[i][j] = idx++;

        // For each pair, consider all adjacent cell pairs (u,v) where |ru-rv|+|cu-cv|=1
        // and compute minimal cost to place that pair on those two cells.
        // Then we add that as an edge between u and v in both directions (since matching is undirected).
        for (int id = 1; id <= maxId; id++) {
            Pos s1 = p1[id];
            Pos s2 = p2[id];
            int r1 = s1.r, c1 = s1.c;
            int r2 = s2.r, c2 = s2.c;

            for (int u = 0; u < N; u++) {
                int ru = row[u], cu = col[u];
                // neighbors of (ru,cu)
                int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
                for (int[] d : dirs) {
                    int rv = ru + d[0], cv = cu + d[1];
                    if (rv < 0 || rv >= n || cv < 0 || cv >= m) continue;
                    int v = idCell[rv][cv];

                    // cost to move the two shoes of this pair to cells u and v
                    int cA = Math.abs(r1 - ru) + Math.abs(c1 - cu)
                           + Math.abs(r2 - rv) + Math.abs(c2 - cv);
                    int cB = Math.abs(r1 - rv) + Math.abs(c1 - cv)
                           + Math.abs(r2 - ru) + Math.abs(c2 - cu);
                    int best = Math.min(cA, cB);

                    if (best < cost[u][v]) cost[u][v] = best;
                    if (best < cost[v][u]) cost[v][u] = best;
                }
            }
        }

        // Hungarian algorithm for minimum weight perfect matching on bipartite graph
        int[] u = new int[N + 1];
        int[] v = new int[N + 1];
        int[] p = new int[N + 1];
        int[] way = new int[N + 1];

        for (int i = 1; i <= N; i++) {
            p[0] = i;
            int j0 = 0;
            int[] minv = new int[N + 1];
            boolean[] used = new boolean[N + 1];
            Arrays.fill(minv, INF);
            Arrays.fill(used, false);
            do {
                used[j0] = true;
                int i0 = p[j0], delta = INF, j1 = 0;
                for (int j = 1; j <= N; j++) {
                    if (used[j]) continue;
                    int cur = cost[i0 - 1][j - 1] - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
                for (int j = 0; j <= N; j++) {
                    if (used[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p[j0] != 0);
            do {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0 != 0);
        }

        long answer = 0;
        for (int j = 1; j <= N; j++) {
            int i = p[j];
            answer += cost[i - 1][j - 1];
        }

        System.out.println(answer);
    }
}

