        int[][] a = new int[n][m];
        int maxId = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                a[i][j] = fs.nextInt();
                if (a[i][j] > maxId) maxId = a[i][j];
            }
