        PairPos[] pos = new PairPos[maxId + 1];
        for (int i = 1; i <= maxId; i++) pos[i] = new PairPos();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int id = a[i][j];
                PairPos p = pos[id];
                if (p.r1 == -1) {
                    p.r1 = i;
                    p.c1 = j;
                } else {
                    p.r2 = i;
                    p.c2 = j;
                }
            }
        }

        int totalCells = n * m;
        int half = totalCells / 2;

        // Build bipartite graph: left side = pair index (1..maxId), right side = adjacency slot index
        // Each adjacency slot corresponds to one cell (u) and one of its neighbors (v) with u<v in index
        // But we only need adjacency slots as unique indices; we will map them via (u,v).
        // However, we don't need explicit mapping; we can just index slots sequentially.

        // Precompute cell index
        int[][] idx = new int[n][m];
        int cur = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                idx[i][j] = cur++;

        // For each adjacency (u,v) (Manhattan neighbors), we create a slot with index s
        // and edges from pairs that can occupy it with cost 0 or 1.
        // But we only need cost 0 edges for maximum matching; cost 1 edges are implicit.
        // However, we must ensure that every pair has at least one adjacency; guaranteed by grid and even cells.

        // We'll build adjacency list for left side (pairs) to right side (slots) with cost0 edges only.
        // For each pair, for each adjacency slot that can host it with cost0, add edge.
        // Then maximum matching size = number of pairs that can be placed with cost0.
        // Answer = 2 * (number of pairs - matchedPairs).

        // Build all adjacency slots and for each slot, determine which pair can be placed with cost0.
        // But number of slots is O(n*m), up to 6400; pairs up to 3200; edges manageable.

        // Map from slot index to list of pairs with cost0
        ArrayList<Integer>[] pairEdges = new ArrayList[maxId + 1];
        for (int i = 1; i <= maxId; i++) pairEdges[i] = new ArrayList<>();

        int slotCount = 0;
        // We'll also need for matching: for each pair, list of slots
        // We'll assign slot indices sequentially and store adjacency in pairEdges.

        // To store slot endpoints for cost computation if needed (not needed for matching)
        // but not required.

        int[][] slotU = new int[n * m * 2][2]; // store endpoints indices (u,v) if needed
        // but we won't use them further.

        int[] dr = {1, 0};
        int[] dc = {0, 1};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int u = idx[i][j];
                for (int d = 0; d < 2; d++) {
                    int ni = i + dr[d];
                    int nj = j + dc[d];
                    if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
                    int v = idx[ni][nj];
                    int slot = slotCount++;
                    slotU[slot][0] = u;
                    slotU[slot][1] = v;

                    // For each pair, check if its two shoes are exactly these two cells
                    // or can be moved with 0 moves (i.e., already there).
                    // Actually cost0 means both shoes already in these two cells.
                    int id1 = a[i][j];
                    int id2 = a[ni][nj];
                    if (id1 == id2) {
                        // This pair already occupies this adjacency with cost0
                        pairEdges[id1].add(slot);
                    }
                }
            }
        }

        // Now we have bipartite graph: left nodes 1..maxId, right nodes 0..slotCount-1
        int[] matchR = new int[slotCount];
        Arrays.fill(matchR, -1);

        int matched = 0;
        for (int p = 1; p <= maxId; p++) {
            boolean[] seen = new boolean[slotCount];
            if (dfs(p, pairEdges, matchR, seen)) matched++;
        }

        int answer = 2 * (maxId - matched);
        System.out.println(answer);
