    static boolean dfs(int u, ArrayList<Integer>[] adj, int[] matchR, boolean[] seen) {
        for (int v : adj[u]) {
            if (seen[v]) continue;
            seen[v] = true;
            if (matchR[v] == -1 || dfs(matchR[v], adj, matchR, seen)) {
                matchR[v] = u;
                return true;
            }
        }
        return false;
    }

